#include <stddef.h>
#include <sqlite3.h>

int import_scores(sqlite3 *db, const int *scores, int n) {
  sqlite3_stmt *stmt = NULL;
  int rc = sqlite3_prepare_v2(db, "INSERT INTO scores (value) VALUES (?)", -1, &stmt, NULL);
  if (rc != SQLITE_OK) return rc;
  for (int i = 0; i < n; i++) {
    sqlite3_bind_int(stmt, 1, scores[i]);
    rc = sqlite3_step(stmt);
    if (rc != SQLITE_DONE) break;
    sqlite3_reset(stmt);
  }
  sqlite3_finalize(stmt);
  return rc == SQLITE_DONE ? SQLITE_OK : rc;
}

